package io.github.jesterportfolio.hearth.story;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class StoryPreparationSettingsTest {
    static Map<String,Object> job(){return new HashMap<>(Map.ofEntries(Map.entry("id","one"),Map.entry("run",new UUID(12,1).toString()),Map.entry("world-key","hearth_story:one"),Map.entry("template","source"),Map.entry("template-version","v1"),Map.entry("template-sha256","a".repeat(64)),Map.entry("regions-sha256","b".repeat(64)),Map.entry("entry-x",0.5),Map.entry("entry-y",65),Map.entry("entry-z",0.5),Map.entry("entry-yaw",0),Map.entry("entry-pitch",0),Map.entry("required-regions",List.of("protected"))));}
    static Map<String,Object> settings(){return new HashMap<>(Map.ofEntries(Map.entry("jobs",List.of(job())),Map.entry("content-file","content.yml"),Map.entry("content-sha256","c".repeat(64)),Map.entry("max-template-files",100),Map.entry("max-template-bytes",1000000),Map.entry("reserve-bytes",1000000),Map.entry("db-host","127.0.0.1"),Map.entry("db-port",5432),Map.entry("db-name","hearth"),Map.entry("db-user","hearth"),Map.entry("password-environment","HEARTH_DB_PASSWORD")));}
    @Test void explicitBudgetsAndIdentitiesHaveNoFixtureDefaults(){var s=StoryPreparationSettings.parse(settings());assertEquals(100,s.maxFiles());assertThrows(UnsupportedOperationException.class,()->s.jobs().clear());assertEquals(new UUID(12,1),s.jobs().get("one").run());var run=s.jobs().get("one").run(new UUID(13,1),s.contentHash());assertEquals(new UUID(13,1),run.binding().worldId());assertEquals(s.contentHash(),run.binding().contentHash());}
    @Test void everyRequiredFieldMustBeExplicit(){for(String key:settings().keySet()){var m=settings();m.remove(key);assertThrows(RuntimeException.class,()->StoryPreparationSettings.parse(m),key);}for(String key:job().keySet()){var m=settings();var j=job();j.remove(key);m.put("jobs",List.of(j));assertThrows(RuntimeException.class,()->StoryPreparationSettings.parse(m),key);}}
    @Test void duplicateJobRunOrWorldKeyCannotAllocateTwice(){for(String key:List.of("id","run","world-key")){var m=settings();var j=job();j.put("id","two");j.put("run",new UUID(12,2).toString());j.put("world-key","hearth_story:two");j.put(key,job().get(key));m.put("jobs",List.of(job(),j));assertThrows(RuntimeException.class,()->StoryPreparationSettings.parse(m),key);}}
    @Test void primaryForeignNamespaceAliasesAndUnsafeEntryAreRejected(){for(var change:List.of(Map.of("world-key","minecraft:overworld"),Map.of("world-key","hearth_verify:test"),Map.of("world-key","hearth_story:../old"),Map.of("template","../old"),Map.of("template","/absolute"),Map.of("entry-x",Double.NaN),Map.of("entry-pitch",91),Map.of("required-regions",List.of()))){var m=settings();var j=job();j.putAll(change);m.put("jobs",List.of(j));assertThrows(RuntimeException.class,()->StoryPreparationSettings.parse(m));}}
    @Test void budgetsAndConnectionStringsCannotExpandImplicitly(){for(var change:List.of(Map.of("max-template-files",0),Map.of("max-template-files",100001),Map.of("max-template-bytes",13L*1024*1024*1024),Map.of("reserve-bytes",0),Map.of("db-port",5432.5),Map.of("content-file","../content.yml"),Map.of("password-environment","secret=value"))){var m=settings();m.putAll(change);assertThrows(RuntimeException.class,()->StoryPreparationSettings.parse(m));}}
}
